def replace_digits_with_words(s):
    words = ['zero', 'one', 'two', 'three', 'four', 'five', 'six', 'seven', 'eight', 'nine']
    result = []
    digits = '0123456789'
    for ch in s:
        if ch in digits:
            result.append(words[int(ch)])
        else:
            result.append(ch)
    return ''.join(result)

def count_char_type_groups(s):
    def cat(c):
        if c.isalpha():
            return 'alpha'
        elif c.isdigit():
            return 'digit'
        else:
            return 'other'
    if not s:
        return 0
    count = 1
    prev = cat(s[0])
    for c in s[1:]:
        cur = cat(c)
        if cur != prev:
            count += 1
        prev = cur
    return count

def count_vowel_runs(s):
    vowels = set('aeiouAEIOU')
    count = 0
    in_run = False
    for c in s:
        if c in vowels:
            if not in_run:
                count += 1
                in_run = True
        else:
            in_run = False
    return count

def count_max_nesting_depth(s):
    depth = 0
    max_depth = 0
    openers = set('([{')
    closers = set(')]}')
    for c in s:
        if c in openers:
            depth += 1
            if depth > max_depth:
                max_depth = depth
        elif c in closers:
            depth = max(depth - 1, 0)
    return max_depth

def find_repeated_words(s):
    words = s.split()
    counts = {}
    order = []
    for w in words:
        lw = w.lower()
        if lw not in counts:
            counts[lw] = 0
            order.append(lw)
        counts[lw] += 1
    return [w for w in order if counts[w] >= 2]

def is_valid_hex_string(s):
    if not s:
        return False
    hexdigits = set('0123456789abcdefABCDEF')
    return all(c in hexdigits for c in s)

