def common_suffix_length(a, b):
    if not a or not b:
        return 0
    n = min(len(a), len(b))
    i = 0
    while i < n and a[-1 - i] == b[-1 - i]:
        i += 1
    return i

def is_one_edit_away(a, b):
    la, lb = len(a), len(b)
    if abs(la - lb) > 1:
        return False
    if la == lb:
        diff = sum(1 for x, y in zip(a, b) if x != y)
        return diff <= 1
    if la > lb:
        a, b = b, a
        la, lb = lb, la
    i = j = 0
    found_diff = False
    while i < la and j < lb:
        if a[i] != b[j]:
            if found_diff:
                return False
            found_diff = True
            j += 1
        else:
            i += 1
            j += 1
    return True

def count_substring_occurrences_nonoverlapping(s, sub):
    if sub == '':
        return 0
    count = 0
    i = 0
    while True:
        idx = s.find(sub, i)
        if idx == -1:
            break
        count += 1
        i = idx + len(sub)
    return count

def find_all_occurrence_indices(s, sub):
    if sub == '':
        return []
    result = []
    i = 0
    while True:
        idx = s.find(sub, i)
        if idx == -1:
            break
        result.append(idx)
        i = idx + 1
    return result
